/* @lc app=leetcode id=3594 lang=kotlin */ class Solution { fun minTime(n: Int, k: Int, m: Int, time: IntArray, mul: DoubleArray): Double = (1 shl n).let { F -> IntArray(F) { s -> (0 until n).filter { s shr it and 1 == 1 }.maxOfOrNull { time[it] } ?: 0 }.let { mt -> Array(F) { mask -> generateSequence(mask) { s -> if (s == 0) null else (s - 1) and mask }.filter { it != 0 && Integer.bitCount(it) <= k }.toList().toIntArray() }.let { subs -> DoubleArray(F * m * 2) { 1e18 }.also { it[(F - 1) * m * 2] = 0.0 }.let { dist -> java.util.PriorityQueue<Pair<Double, Int>>(compareBy<Pair<Double, Int>> { it.first }).also { it.add(0.0 to (F - 1) * m * 2) }.let { pq -> DoubleArray(1) { 1e18 }.let { best -> generateSequence { pq.poll() }.filter { (dd, s) -> dd <= dist[s] }.forEach { (dd, s) -> (s % 2).let { side -> (s / 2 % m).let { st -> (s / 2 / m).let { mask -> if (side == 0) subs[mask].forEach { g -> (mt[g] * mul[st]).let { d -> ((st + Math.floor(d).toInt()) % m).let { ns -> (mask xor g).let { nm -> if (nm == 0) best.set(0, minOf(best[0], dd + d)) else ((nm * m + ns) * 2 + 1).let { ni -> if (dd + d < dist[ni]) pq.add(dd + d to ni).also { dist[ni] = dd + d } } } } } } else ((F - 1) xor mask).let { far -> (0 until n).filter { far shr it and 1 == 1 }.forEach { r -> (time[r] * mul[st]).let { rt -> ((st + Math.floor(rt).toInt()) % m).let { ns -> (mask or (1 shl r)).let { nm -> ((nm * m + ns) * 2).let { ni -> if (dd + rt < dist[ni]) pq.add(dd + rt to ni).also { dist[ni] = dd + rt } } } } } } } } } } }.let { if (best[0] >= 1e17) -1.0 else best[0] } } } } } } } }